fn main() {
    let raw = "GET /hello HTTP/1.1\r\nHost: localhost\r\nUser-Agent: demo\r\n\r\n";
    println!("{raw:?}");   // {:?} shows the \r\n escapes instead of line breaks
    for line in raw.lines() {
        println!("line: {line}");
    }
    let (head, body) = raw.split_once("\r\n\r\n").unwrap();
    println!("head has {} lines, body is {body:?}", head.lines().count());
}

// Output:
// "GET /hello HTTP/1.1\r\nHost: localhost\r\nUser-Agent: demo\r\n\r\n"
// line: GET /hello HTTP/1.1
// line: Host: localhost
// line: User-Agent: demo
// line:
// head has 3 lines, body is ""

use std::collections::HashMap;
use std::fmt;

#[derive(Clone, Copy)]   // so that route can copy req.method into a tuple
enum Method {
    Get,
    Post,
}

struct Request {
    method: Method,
    path: String,
    headers: HashMap<String, String>,
    body: String,
}

enum ParseError {
    Empty,
    BadRequestLine(String),
    UnknownMethod(String),
}

impl fmt::Display for ParseError {
    fn fmt(&self, f: &mut fmt::Formatter) -> fmt::Result {
        match self {
            ParseError::Empty => write!(f, "empty request"),
            ParseError::BadRequestLine(line) => write!(f, "bad request line '{line}'"),
            ParseError::UnknownMethod(m) => write!(f, "unknown method {m}"),
        }
    }
}

fn parse_request(raw: &str) -> Result<Request, ParseError> {
    let (head, body) = raw.split_once("\r\n\r\n").unwrap_or((raw, ""));
    let mut lines = head.lines();
    // ok_or turns None into the given error, so that ? can return it.
    let request_line = lines.next().ok_or(ParseError::Empty)?;
    let parts: Vec<&str> = request_line.split_whitespace().collect();
    if parts.len() != 3 {
        return Err(ParseError::BadRequestLine(request_line.to_string()));
    }
    let method = match parts[0] {
        "GET" => Method::Get,
        "POST" => Method::Post,
        other => return Err(ParseError::UnknownMethod(other.to_string())),
    };
    let mut headers = HashMap::new();
    for line in lines {
        if let Some((name, value)) = line.split_once(':') {
            headers.insert(name.trim().to_lowercase(), value.trim().to_string());
        }
    }
    Ok(Request {
        method,
        path: parts[1].to_string(),
        headers,
        body: body.to_string(),
    })
}

struct Response {
    status: u16,
    content_type: &'static str,
    body: String,
}

impl Response {
    fn new(status: u16, content_type: &'static str, body: &str) -> Response {
        Response { status, content_type, body: body.to_string() }
    }

    fn to_text(&self) -> String {
        let reason = match self.status {
            200 => "OK",
            400 => "Bad Request",
            404 => "Not Found",
            _ => "Unknown",
        };
        format!(
            "HTTP/1.1 {} {}\r\nContent-Type: {}\r\nContent-Length: {}\r\n\r\n{}",
            self.status, reason, self.content_type, self.body.len(), self.body
        )
    }
}

fn route(req: &Request) -> Response {
    match (req.method, req.path.as_str()) {
        (Method::Get, "/") => Response::new(200, "text/html", "<h1>Welcome</h1>"),
        (Method::Get, "/hello") => Response::new(200, "text/plain", "Hello, world!"),
        (Method::Get, "/agent") => {
            // get gives an Option<&String>. map changes the value inside Some (to a &str);
            // unwrap_or supplies "unknown" when the header is missing.
            let agent = req.headers.get("user-agent").map(|a| a.as_str()).unwrap_or("unknown");
            Response::new(200, "text/plain", &format!("You are {agent}"))
        }
        (Method::Post, "/echo") => Response::new(200, "text/plain", &req.body),
        _ => Response::new(404, "text/plain", "Not found"),
    }
}

fn handle(raw: &str) -> Response {
    match parse_request(raw) {
        Ok(req) => route(&req),
        Err(e) => Response::new(400, "text/plain", &format!("Bad request: {e}")),
    }
}

fn main() {
    let first = handle("GET / HTTP/1.1\r\nHost: localhost\r\n\r\n");
    println!("{}", first.to_text());
    println!("-----");

    let requests = [
        "GET /agent HTTP/1.1\r\nUser-Agent: curl/8.0\r\n\r\n",
        "POST /echo HTTP/1.1\r\nContent-Length: 5\r\n\r\nhello",
        "GET /missing HTTP/1.1\r\n\r\n",
        "FETCH / HTTP/1.1\r\n\r\n",
        "GET /\r\n\r\n",
        "",
    ];
    for raw in requests {
        let response = handle(raw);
        println!("{} {}", response.status, response.body);
    }
}

// Output:
// HTTP/1.1 200 OK
// Content-Type: text/html
// Content-Length: 16
//
// <h1>Welcome</h1>
// -----
// 200 You are curl/8.0
// 200 hello
// 404 Not found
// 400 Bad request: unknown method FETCH
// 400 Bad request: bad request line 'GET /'
// 400 Bad request: empty request

