fn route(path: &str) -> (u16, &'static str) {
    match path {
        "/" => (200, "Home page"),
        "/about" => (200, "About us"),
        _ => (404, "Not found"),
    }
}

fn main() {
    for path in ["/", "/about", "/nope"] {
        let (status, body) = route(path);
        println!("{status} {body}");
    }
}
